import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


# ---
def make_student(last_name, first_name):
    student_id = f"{last_name}-{first_name}"
    return Student(student_id, last_name, first_name, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Varrow", "Ines"),
            make_student("Quillon", "Sefa")
        ]

    def test_rows_are_ordered_by_last_name(self):
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Juno",
            "Row 2: Quillon, Sefa | Varrow, Ines"
        ]
        rows = seating_rows(self.students, 2)
        self.assertEqual(rows, expected)

    def test_short_final_row(self):
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Juno"
            " | Quillon, Sefa",
            "Row 2: Varrow, Ines"
        ]
        rows = seating_rows(self.students, 3)
        self.assertEqual(rows, expected)

    def test_one_row_when_seats_outnumber_students(self):
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Juno"
            " | Quillon, Sefa | Varrow, Ines"
        ]
        rows = seating_rows(self.students, 10)
        self.assertEqual(rows, expected)

    def test_zero_seats_per_row(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_per_row(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -2)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
